impl ScaleFrontierCard7{pub fn validate(&self)->Result<(),ScaleFrontierError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.candidate_order.is_empty()||!ord(&self.candidate_order)||!ord(&self.selected_order)||!ord(&self.rejected_order)||!ord(&self.unknown_order)||!ord(&self.omitted_order)||!ord(&self.uncertainty_order)||!ord(&self.negative_evidence_order)||!ord(&self.scale_order)||!ord(&self.slo_order)||!dig(&self.replay_identity)||!dig(&self.frontier_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.frontier_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY{return Err(ScaleFrontierError::Output("scale identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.candidate_order.iter().cloned());let parts=self.selected_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.candidate_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(ScaleFrontierError::Output("scale states do not partition".into()))}Ok(())}}
pub fn evaluate(request:&ScaleFrontierRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<ScaleFrontierCard7,ScaleFrontierError>{if !ne(&request.request_id)||!ne(&request.scope)||request.candidates.is_empty()||request.required_scale_order.is_empty()||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_scale_order)||!ord(&request.adversarial_events){return Err(ScaleFrontierError::Invalid("scale identity, candidates, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.candidates.clone();rows.sort_by(|a,b|a.candidate_id.cmp(&b.candidate_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut selected=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut scales=BTreeSet::new();let mut benchmarks=BTreeSet::new();for c in &rows{if !seen.insert(c.candidate_id.clone())||!ne(&c.candidate_id)||!ne(&c.scale)||!dig(&c.benchmark_digest)||!dig(&c.replay_identity)||!c.local||!c.aggregate_only{return Err(ScaleFrontierError::Invalid("candidate identity, digest, or locality is invalid".into()))}order.push(c.candidate_id.clone());scales.insert(c.scale.clone());benchmarks.insert(c.benchmark_digest.clone());if c.negative_result{negative.insert(format!("{}:negative-result",c.candidate_id));}if c.replay_identity!=request.replay_identity{omitted.insert(c.candidate_id.clone());}else if c.evidence_state=="unknown"||c.evidence_state=="unmeasured"{unknown.insert(c.candidate_id.clone());}else if c.evidence_state=="proven"||c.evidence_state=="supported"{if c.throughput_milli>=request.min_throughput_milli&&c.latency_milli<=request.max_latency_milli&&c.cost_milli<=request.max_cost_milli{selected.insert(c.candidate_id.clone());}else{rejected.insert(c.candidate_id.clone());uncertainty.insert(format!("{}:slo-or-cost",c.candidate_id));}}else{rejected.insert(c.candidate_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.network_available||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty();if global{omitted.extend(order.iter().cloned());selected.clear();rejected.clear();unknown.clear();}let required=BTreeSet::from_iter(request.required_scale_order.iter().cloned());let selected_scales=rows.iter().filter(|c|selected.contains(&c.candidate_id)).map(|c|c.scale.clone()).collect::<BTreeSet<_>>();let disposition=if global{"blocked"}else if !required.is_subset(&selected_scales)||!rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"unresolved"}else{"qualified"};let slo=vec![format!("throughput>= {}",request.min_throughput_milli),format!("latency<= {}",request.max_latency_milli),format!("cost<= {}",request.max_cost_milli)];let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"disposition":disposition,"candidate_order":order,"selected_order":selected.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"scale_order":scales.into_iter().collect::<Vec<_>>(),"slo_order":slo,"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|ScaleFrontierError::Output(e.to_string()))?;payload["frontier_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-scale-frontier:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["uncertainty_order"],"benchmark_digests":benchmarks.into_iter().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:scale-frontier-card:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:ScaleFrontierCard7=serde_json::from_value(payload).map_err(|e|ScaleFrontierError::Output(e.to_string()))?;out.validate()?;Ok(out)}
